/* ============================================================================
 * GDOP base tokens — THE source of truth for every color and design token.
 *
 *   • The docs Colors page parses this file and renders it (app/docs/foundations/colors).
 *   • The shadcn registry item "base" ships this file as-is (registry.json → public/r/base.json).
 *   • The @theme block at the bottom is GENERATED from the declarations below
 *     (`npm run tokens:sync`). Edit tokens here; never edit the generated block.
 *
 * Authoring rules (the parser relies on them):
 *   1. Declarations live in `:root { }` (light) and `.dark { }` (overrides only).
 *   2. A comment line of the form  @group <kind> <id>: <description>  starts a group
 *      (see the groups below for examples).
 *      kinds: scale | semantic | tone | other.  scale/tone ids must match the token names:
 *      --<id>-<step> for scales, --tone-<id>-<role> for tones.
 *   3. One declaration per line. A short trailing comment becomes the token's description.
 *   4. Components use semantic + tone tokens. Scales are primitives.
 *
 * Install target: ~/app/base.css, then `@import "./base.css";` after `@import "tailwindcss";`.
 * ========================================================================== */

@custom-variant dark (&:is(.dark *));

:root {
  /* @group semantic surfaces: Page, card and popover surfaces with their text. */
  --background: oklch(0.9581 0 0);
  --foreground: oklch(0.3134 0.0234 253.627);
  --card: oklch(0.9774 0.0042 236.4961);
  --card-foreground: oklch(0.2022 0.011 151.1628);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.2505 0.0149 235.6259);

  /* @group semantic actions: Buttons and emphasis: primary, secondary, accent, destructive. */
  --primary: oklch(0.6112 0.1217 248.9572);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.9122 0.0111 243.6627);
  --secondary-foreground: oklch(0.4186 0.0133 235.133);
  --accent: oklch(0.9122 0.0111 243.6627);
  --accent-foreground: oklch(0.2505 0.0149 235.6259);
  --destructive: oklch(0.1931 0.0037 164.6298);
  --destructive-foreground: oklch(1 0 0);

  /* @group semantic content: Subdued surfaces and secondary text. */
  --muted: oklch(0.9209 0.0128 244.2626);
  --muted-foreground: oklch(0.6027 0.0062 211.0375);

  /* @group semantic form: Borders, inputs and focus rings. */
  --border: oklch(0.884 0.0067 208.7806);
  --input: oklch(0.745 0.0121 252.1201);
  --ring: oklch(0.6112 0.1217 248.9572);

  /* @group semantic sidebar: Navigation sidebar surfaces. */
  --sidebar: oklch(0.959 0.0059 239.8204);
  --sidebar-foreground: oklch(0.3571 0.0041 196.9738);
  --sidebar-primary: oklch(0.6112 0.1217 248.9572);
  --sidebar-primary-foreground: oklch(0.9881 0 0);
  --sidebar-accent: oklch(0.9122 0.0111 243.6627);
  --sidebar-accent-foreground: oklch(0.325 0 0);
  --sidebar-border: oklch(0.9401 0 0);
  --sidebar-ring: oklch(0.7731 0 0);

  /* @group semantic charts: Data-visualization series colors. */
  --chart-1: oklch(0.5098 0.132 257.5458);
  --chart-2: oklch(0.736 0.1191 266.5038);
  --chart-3: oklch(0.8467 0.0177 248.0373);
  --chart-4: oklch(0.8977 0.0274 260.3158);
  --chart-5: oklch(0.4893 0.1504 261.9302);

  /* @group other shape: Corner radius. sm/md/lg/xl derive from this. */
  --radius: 0.5rem;

  --shadow-x: 0px;
  --shadow-y: 2px;
  --shadow-blur: 4px;
  --shadow-spread: 0px;
  --shadow-opacity: 0.1;
  --shadow-color: #000000;
  --shadow-2xs: 0px 2px 4px 0px hsl(0 0% 0% / 0.05);
  --shadow-xs: 0px 2px 4px 0px hsl(0 0% 0% / 0.05);
  --shadow-sm:
    0px 2px 4px 0px hsl(0 0% 0% / 0.1), 0px 1px 2px -1px hsl(0 0% 0% / 0.1);
  --shadow:
    0px 2px 4px 0px hsl(0 0% 0% / 0.1), 0px 1px 2px -1px hsl(0 0% 0% / 0.1);
  --shadow-md:
    0px 2px 4px 0px hsl(0 0% 0% / 0.1), 0px 2px 4px -1px hsl(0 0% 0% / 0.1);
  --shadow-lg:
    0px 2px 4px 0px hsl(0 0% 0% / 0.1), 0px 4px 6px -1px hsl(0 0% 0% / 0.1);
  --shadow-xl:
    0px 2px 4px 0px hsl(0 0% 0% / 0.1), 0px 8px 10px -1px hsl(0 0% 0% / 0.1);
  --shadow-2xl: 0px 2px 4px 0px hsl(0 0% 0% / 0.25);

  --tracking-normal: -0.01em;

  --spacing: 0.25rem;
}

.dark {
  --background: oklch(0.1776 0 0);
  --foreground: oklch(0.7905 0.0126 259.8241);
  --card: oklch(0.2638 0.0024 247.9155);
  --card-foreground: oklch(0.9755 0.0045 258.3245);
  --popover: oklch(0.3046 0.0023 247.9001);
  --popover-foreground: oklch(0.9176 0.0026 228.7865);
  --primary: oklch(0.6576 0.1208 252.0832);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.9774 0.0042 236.4961);
  --secondary-foreground: oklch(0.3046 0.0023 247.9001);
  --muted: oklch(0.2171 0.0025 247.9411);
  --muted-foreground: oklch(0.7559 0.0125 239.9659);
  --accent: oklch(0.2038 0.0067 258.3676);
  --accent-foreground: oklch(0.959 0.0059 239.8204);
  --destructive: oklch(0.6368 0.2078 25.3313);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.3506 0.0066 248.0169);
  --input: oklch(0.4217 0.0084 248.028);
  --ring: oklch(0.6576 0.1208 252.0832);
  --sidebar: oklch(0.2344 0.0024 247.9303);
  --sidebar-foreground: oklch(0.7905 0.0126 259.8241);
  --sidebar-primary: oklch(0.325 0 0);
  --sidebar-primary-foreground: oklch(0.9881 0 0);
  --sidebar-accent: oklch(0.1673 0.0016 196.9991);
  --sidebar-accent-foreground: oklch(0.7905 0.0126 259.8241);
  --sidebar-border: oklch(0.9401 0 0);
  --sidebar-ring: oklch(0.7731 0 0);
  --chart-1: oklch(0.5098 0.132 257.5458);
  --chart-2: oklch(0.736 0.1191 266.5038);
  --chart-3: oklch(0.2038 0.0067 258.3676);
  --chart-4: oklch(0.3361 0.0333 253.9085);
  --chart-5: oklch(0.4893 0.1504 261.9302);
  --radius: 0.5rem;
  --shadow-x: 0px;
  --shadow-y: 4px;
  --shadow-blur: 8px;
  --shadow-spread: 0px;
  --shadow-opacity: 0.3;
  --shadow-color: #000000;
  --shadow-2xs: 0px 4px 8px 0px hsl(0 0% 0% / 0.15);
  --shadow-xs: 0px 4px 8px 0px hsl(0 0% 0% / 0.15);
  --shadow-sm:
    0px 4px 8px 0px hsl(0 0% 0% / 0.3), 0px 1px 2px -1px hsl(0 0% 0% / 0.3);
  --shadow:
    0px 4px 8px 0px hsl(0 0% 0% / 0.3), 0px 1px 2px -1px hsl(0 0% 0% / 0.3);
  --shadow-md:
    0px 4px 8px 0px hsl(0 0% 0% / 0.3), 0px 2px 4px -1px hsl(0 0% 0% / 0.3);
  --shadow-lg:
    0px 4px 8px 0px hsl(0 0% 0% / 0.3), 0px 4px 6px -1px hsl(0 0% 0% / 0.3);
  --shadow-xl:
    0px 4px 8px 0px hsl(0 0% 0% / 0.3), 0px 8px 10px -1px hsl(0 0% 0% / 0.3);
  --shadow-2xl: 0px 4px 8px 0px hsl(0 0% 0% / 0.75);
}

/* Non-color theme wiring (hand-written). */
@theme inline {
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);

  --shadow-2xs: var(--shadow-2xs);
  --shadow-xs: var(--shadow-xs);
  --shadow-sm: var(--shadow-sm);
  --shadow: var(--shadow);
  --shadow-md: var(--shadow-md);
  --shadow-lg: var(--shadow-lg);
  --shadow-xl: var(--shadow-xl);
  --shadow-2xl: var(--shadow-2xl);

  --tracking-tighter: calc(var(--tracking-normal) - 0.05em);
  --tracking-tight: calc(var(--tracking-normal) - 0.025em);
  --tracking-normal: var(--tracking-normal);
  --tracking-wide: calc(var(--tracking-normal) + 0.025em);
  --tracking-wider: calc(var(--tracking-normal) + 0.05em);
  --tracking-widest: calc(var(--tracking-normal) + 0.1em);
}

/* @generated:start — color utilities, rebuilt by `npm run tokens:sync`. Do not edit. */
@theme inline {
  /* semantic: surfaces */
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  /* semantic: actions */
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  /* semantic: content */
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  /* semantic: form */
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  /* semantic: sidebar */
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);
  /* semantic: charts */
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  html {
    @apply bg-sidebar;
  }
  body {
    @apply bg-background text-foreground antialiased;
  }
  :focus-visible {
    @apply outline-ring outline-2 outline-offset-2;
  }
  button:not(:disabled),
  [role="button"]:not(:disabled) {
    cursor: pointer;
  }
}
/* @generated:end */
